reset role;
set role authenticated;
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
do $$ declare e uuid; p uuid; rev integer; r jsonb; chave uuid:=gen_random_uuid(); d jsonb; atual timestamptz; begin
  r:=pieggi.salvar_evento('20000000-0000-4000-8000-000000000001',null,null,'{"titulo":"Proposta fixture","tabela_preco":"Externos","pax":30,"data_evento":"2099-10-06","horario_inicio":"09:00","horario_fim":"12:00","logradouro":"Rua fixture","numero_endereco":"1","bairro":"Centro","cidade":"São Paulo","uf":"SP","cep":"01001000","contato_local_nome":"Contato fixture","contato_local_telefone":"11999999999"}','{"nome":"Cliente proposta fixture","tipo":"PF"}');e:=(r->'evento'->>'id')::uuid;
  d:='{"briefing":{"startse":false,"categoria":"EXTERNOS","restricoesConfirmadas":true,"restricoes":"","restritos":0,"cobrancaRestritos":"SEM_RESTRICOES","escopo":"Coffee break sem flores, itens confirmados."},"itens":[{"nome":"Coffee break confirmado","servico":"Coffee manhã","quantidade":3,"unidade":"PAX","preco":11.49}],"desconto":0.01,"taxas":2.15,"custoEstimado":10,"fontePreco":"Tabela comercial fixture confirmada","alteracoes":"Primeira revisão conferida","validade":"2099-12-31"}';
  r:=pieggi.salvar_proposta(e,1,d,chave);p:=(r->>'id')::uuid;
  perform pieggi.salvar_proposta(e,1,d,chave);
  if (select count(*) from pieggi.propostas where evento_id=e)<>1 then raise exception 'TESTE: tentativa duplicou versão';end if;
  if (select total from pieggi.propostas where id=p)<>36.61 then raise exception 'TESTE: total perdeu centavos';end if;
  begin perform pieggi.salvar_proposta(e,1,d||'{"taxas":2}',chave);raise exception 'TESTE: idempotência aceita alteração';exception when raise_exception then if SQLERRM<>'Chave utilizada por outra proposta.' then raise;end if;end;
  begin perform pieggi.aprovar_proposta(e,1,p,true);raise exception 'TESTE: revisão concorrente aceita';exception when serialization_failure then null;end;
  select revisao into rev from pieggi.eventos where id=e;
  perform pieggi.aprovar_proposta(e,rev,p,true);
  if (select valor_venda from pieggi.evento_valores where evento_id=e)<>36.61 then raise exception 'TESTE: venda sem origem aprovada';end if;
  select revisao into rev from pieggi.eventos where id=e;
  begin perform pieggi.operar_financeiro(e,rev,'VALORES_SALVAR','{"venda":99,"custoEstimado":10}');raise exception 'TESTE: financeiro sobrescreveu proposta';exception when raise_exception then if SQLERRM<>'Revise a proposta para alterar os valores aprovados.' then raise;end if;end;
  select atualizado_em into atual from pieggi.eventos where id=e;
  perform pieggi.salvar_evento('20000000-0000-4000-8000-000000000001',e,atual,'{"pax":35}',null);
  if exists(select 1 from pieggi.propostas where evento_id=e and status='APROVADA') or (select valor_venda from pieggi.evento_valores where evento_id=e) is not null then raise exception 'TESTE: briefing mudou sem invalidar venda';end if;
  select revisao into rev from pieggi.eventos where id=e;
  r:=pieggi.salvar_proposta(e,rev,d,gen_random_uuid());p:=(r->>'id')::uuid;
  select revisao into rev from pieggi.eventos where id=e;perform pieggi.aprovar_proposta(e,rev,p,true);
  select revisao into rev from pieggi.eventos where id=e;
  begin perform pieggi.salvar_proposta(e,rev,jsonb_set(d,'{briefing,categoria}','"WTC"'),gen_random_uuid());raise exception 'TESTE: taxa cobrada para WTC';exception when raise_exception then if SQLERRM<>'Esta tabela é isenta de taxas e logística.' then raise;end if;end;
  set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
  if exists(select 1 from pieggi.propostas where evento_id=e) then raise exception 'TESTE: proposta monetária vazou para cozinha';end if;
  begin perform pieggi.salvar_proposta(e,rev,d,gen_random_uuid());raise exception 'TESTE: cozinha criou proposta';exception when insufficient_privilege then null;end;
  set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
  r:=pieggi.proposta_operacional(e);
  if r::text like '%preco%' or r::text like '%custo%' or r::text like '%total%' or r->>'versao'<>'2' then raise exception 'TESTE: handoff errado ou vazando preço';end if;
  set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000003';
  if exists(select 1 from pieggi.propostas where evento_id=e) then raise exception 'TESTE: outra empresa acessou proposta';end if;
  begin perform pieggi.proposta_operacional(e);raise exception 'TESTE: outra empresa acessou handoff';exception when insufficient_privilege then null;end;
  set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
  select revisao,atualizado_em into rev,atual from pieggi.eventos where id=e;
  r:=pieggi.salvar_proposta(e,rev,d,gen_random_uuid());p:=(r->>'id')::uuid;
  select atualizado_em into atual from pieggi.eventos where id=e;
  begin perform pieggi.salvar_evento('20000000-0000-4000-8000-000000000001',e,atual,'{"etapa_comercial":"CONTRATO_ENVIADO"}',null);raise exception 'TESTE: contrato ignorou rascunho mais novo';exception when raise_exception then if SQLERRM<>'Aprove a proposta vigente antes de formalizar o contrato.' then raise;end if;end;
  select revisao into rev from pieggi.eventos where id=e;perform pieggi.aprovar_proposta(e,rev,p,true);
  select atualizado_em into atual from pieggi.eventos where id=e;
  perform pieggi.salvar_evento('20000000-0000-4000-8000-000000000001',e,atual,'{}','{"nome":"Cliente alterado após aprovação","tipo":"PF"}');
  if exists(select 1 from pieggi.propostas where evento_id=e and status='APROVADA') or pieggi.proposta_operacional(e) is not null then raise exception 'TESTE: edição do cliente não invalidou referência';end if;
end $$;
reset role;
